function LiveVideoTab({ account }) {
  const videoRef = React.useRef(null);
  const streamRef = React.useRef(null);
  const [streamReady, setStreamReady] = useState(false);
  const [filter, setFilter] = useState(LIVE_FILTERS[0]);
  const [isLive, setIsLive] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!navigator.mediaDevices?.getUserMedia) { setError("Camera access is not supported in this browser."); return; }
      try { const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" }, audio: true }); if (cancelled) { stream.getTracks().forEach((track) => track.stop()); return; } streamRef.current = stream; setStreamReady(true); if (videoRef.current) videoRef.current.srcObject = stream; }
      catch { setError("Camera and microphone permissions are required for Live Video."); }
    })();
    return () => { cancelled = true; streamRef.current?.getTracks().forEach((track) => track.stop()); streamRef.current = null; };
  }, []);
  useEffect(() => { if (videoRef.current && streamRef.current) videoRef.current.srcObject = streamRef.current; }, [streamReady]);
  const startTaking = async () => {
    if (!streamRef.current) return;
    let userId = account?.id || null;
    if (!userId) { try { userId = (await supabase.auth.getUser()).data?.user?.id || null; } catch {} }
    if (!userId) { setError("Sign in is required to go live."); return; }
    const profile = talkProfileFromRow(account || {}, { name: "RainX trader", country: "Accra, Ghana", flag: "🇬🇭" });
    const { error: syncError } = await supabase.from("space_talk_participants").upsert({ room_id: "weekly-crypto-talk", user_id: userId, role: "host", name: profile.name, country: profile.country, flag: profile.flag, avatar_url: profile.avatar_url, is_muted: false, is_live: true }, { onConflict: "room_id,user_id" });
    if (syncError) setError("Could not publish your live status."); else setIsLive(true);
  };
  return <div style={{ minHeight: "100dvh", background: "#FFFFFF", padding: "18px 22px 34px", boxSizing: "border-box", color: "#111418" }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><div><h2 style={{ margin: 0, fontSize: 24, letterSpacing: -0.7 }}>Live Video</h2><p style={{ margin: "7px 0 0", color: "#70757B", fontSize: 13 }}>Use your camera to take the stage.</p></div>{isLive && <span style={{ padding: "7px 10px", borderRadius: 14, background: "#E44747", color: "#FFFFFF", fontSize: 12, fontWeight: 800 }}>LIVE</span>}</div><div style={{ position: "relative", marginTop: 18, overflow: "hidden", aspectRatio: "3 / 4", borderRadius: 24, background: "#15171A" }}><video ref={videoRef} autoPlay playsInline muted style={{ width: "100%", height: "100%", display: "block", objectFit: "cover", transform: "scaleX(-1)", filter: filter[1] }} />{!streamReady && <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", padding: 30, color: "#FFFFFF", textAlign: "center" }}>{error || "Starting camera…"}</div>}<span style={{ position: "absolute", left: 14, top: 14, padding: "7px 10px", borderRadius: 14, background: "#11141899", color: "#FFFFFF", fontSize: 12 }}>Camera preview</span></div><div style={{ marginTop: 18 }}><strong style={{ fontSize: 16 }}>Live filters</strong><div style={{ display: "flex", gap: 8, overflowX: "auto", padding: "12px 0 4px", scrollbarWidth: "none" }}>{LIVE_FILTERS.map((option) => <button key={option[0]} type="button" onClick={() => setFilter(option)} style={{ flex: "0 0 auto", border: option[0] === filter[0] ? "2px solid #E1B51A" : "1px solid #E2E4E6", borderRadius: 16, background: option[0] === filter[0] ? "#FFF7D8" : "#FFFFFF", padding: "9px 12px", color: "#111418", fontFamily: FONT, fontSize: 12, fontWeight: option[0] === filter[0] ? 750 : 500 }}>{option[0]}</button>)}</div></div><button type="button" onClick={startTaking} disabled={!streamReady || isLive} style={{ width: "100%", height: 52, marginTop: 20, border: 0, borderRadius: 15, background: isLive ? "#E9EAEC" : "#F4D35E", color: "#111418", fontFamily: FONT, fontSize: 16, fontWeight: 800 }}>{isLive ? "You are LIVE" : "Start Taking"}</button>{error && <p style={{ margin: "12px 0 0", color: "#A52222", fontSize: 13 }}>{error}</p>}</div>;
}

function SpaceTalkDiscoveryScreen({ onOpenLiveRoom, account }) {
  const [activeTab, setActiveTab] = useState(0);
  const [tabDragX, setTabDragX] = useState(0);
  const tabTouchRef = React.useRef(null);
  const rooms = [["Market Outlook 2024", "John Carter", "1.2K", "#F4D35E"], ["Web3 & The Future", "Crypto Lisa", "856", "#2F80ED"]];
  const selectTab = (tab) => { setActiveTab(tab); setTabDragX(0); };
  const onTabTouchStart = (event) => { tabTouchRef.current = event.touches[0].clientX; setTabDragX(0); };
  const onTabTouchMove = (event) => { if (tabTouchRef.current == null) return; const dx = event.touches[0].clientX - tabTouchRef.current; if (Math.abs(dx) > 8) { event.preventDefault(); setTabDragX(Math.max(-120, Math.min(120, dx))); } };
  const onTabTouchEnd = () => { if (tabTouchRef.current == null) return; const dx = tabDragX; if (dx < -50) selectTab(Math.min(2, activeTab + 1)); else if (dx > 50) selectTab(Math.max(0, activeTab - 1)); else setTabDragX(0); tabTouchRef.current = null; };
  const talkPage = <div style={{ minWidth: 0, flex: "0 0 33.333%", padding: "18px 22px 36px", boxSizing: "border-box", color: "#111418" }}><section style={{ minHeight: 158, borderRadius: 16, padding: "18px 16px 15px", boxSizing: "border-box", background: "radial-gradient(circle at 88% 5%,#FFF0A9 0 8%,transparent 33%), linear-gradient(135deg,#FFD944,#F4B914)", position: "relative", overflow: "hidden", boxShadow: "0 4px 13px #D9A91424" }}><div style={{ position: "absolute", right: -12, bottom: -34, width: 172, height: 110, borderRadius: "50%", border: "1px solid #FFF4B766", transform: "rotate(-20deg)" }} /><strong style={{ display: "block", fontSize: 19, lineHeight: 1.1, letterSpacing: -0.3 }}>Weekly Crypto Talk</strong><p style={{ margin: "7px 0 0", maxWidth: 210, fontSize: 16, lineHeight: 1.35, fontWeight: 500 }}>Market insights &amp;<br />trend discussion</p><div style={{ position: "absolute", left: 16, bottom: 14, display: "flex", alignItems: "center" }}>{[0, 1, 2].map((item) => <span key={item} style={{ marginLeft: item ? -7 : 0, borderRadius: "50%" }}><PlaceholderAvatar size={31} /></span>)}<span style={{ marginLeft: -2, width: 35, height: 31, display: "grid", placeItems: "center", borderRadius: "50%", background: "#FFF2B9", color: "#53504A", fontSize: 14, fontWeight: 700 }}>+24</span></div><button type="button" onClick={() => onOpenLiveRoom(false)} style={{ position: "absolute", right: 14, bottom: 14, height: 44, minWidth: 142, padding: "0 13px 0 18px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 10, border: 0, borderRadius: 17, background: "#111418", color: "#FFFFFF", fontFamily: FONT, fontSize: 15, fontWeight: 750 }}>Join Now <AudioLines size={21} strokeWidth={2.1} color="#F4D35E" /></button></section><section style={{ marginTop: 30 }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><h2 style={{ margin: 0, fontSize: 20, lineHeight: 1.1, letterSpacing: -0.45, fontWeight: 800 }}>People Around the World</h2><span style={{ display: "flex", alignItems: "center", gap: 5, color: "#85888C", fontSize: 14 }}>Live now <i style={{ width: 9, height: 9, borderRadius: "50%", background: "#35A64A", display: "block" }} /></span></div><div style={{ height: 238, marginTop: 7, position: "relative" }}><WorldMap />{TALK_AVATARS.map((avatar, index) => <span key={index} style={{ position: "absolute", left: avatar.left, top: avatar.top }}><PlaceholderAvatar size={avatar.size} /><span style={{ position: "absolute", right: -2, bottom: -2, width: 10, height: 10, borderRadius: "50%", background: "#F4D35E", border: "2px solid #FFFFFF", boxSizing: "border-box" }} /></span>)}<span style={{ position: "absolute", left: "46%", top: "46%" }}><span style={{ position: "absolute", inset: -13, borderRadius: "50%", border: "1px solid #F4D35E" }} /><span style={{ position: "absolute", inset: -7, borderRadius: "50%", border: "1px solid #F4D35E" }} /><PlaceholderAvatar size={50} center /></span></div></section><section style={{ marginTop: 8 }}><div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 13 }}><h2 style={{ margin: 0, fontSize: 20, lineHeight: 1.1, letterSpacing: -0.45, fontWeight: 800 }}>Popular Rooms</h2><button type="button" style={{ border: 0, background: "transparent", color: "#D4A711", fontFamily: FONT, fontSize: 15, fontWeight: 650, padding: 0 }}>See all</button></div>{rooms.map(([title, host, viewers, color]) => <button key={title} type="button" onClick={() => onOpenLiveRoom(false)} style={{ width: "calc(100% - 10px)", marginLeft: 5, minHeight: 72, marginBottom: 8, padding: "9px 12px 9px 9px", display: "flex", alignItems: "center", gap: 12, border: "1px solid #E5E6E8", borderRadius: 17, background: "#FFFFFF", color: "#111418", fontFamily: FONT, textAlign: "left", boxSizing: "border-box" }}><PlaceholderAvatar size={45} /><span style={{ flex: 1, minWidth: 0 }}><strong style={{ display: "block", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontSize: 15, lineHeight: 1.2, fontWeight: 650 }}>{title}</strong><span style={{ display: "block", marginTop: 5, color: "#62676D", fontSize: 13 }}>{host}</span></span><span style={{ display: "flex", alignItems: "center", gap: 11, color: "#62676D", fontSize: 13, whiteSpace: "nowrap" }}><span style={{ padding: "5px 11px", borderRadius: 13, background: color, color: color === "#F4D35E" ? "#111418" : "#FFFFFF", fontWeight: 700 }}>Live</span><span style={{ display: "flex", alignItems: "center", gap: 4 }}><UsersRound size={16} />{viewers}</span></span></button>)}</section><button type="button" onClick={() => onOpenLiveRoom(true)} style={{ width: "100%", height: 52, marginTop: 13, border: 0, borderRadius: 14, background: "#F4D35E", color: "#111418", fontFamily: FONT, fontSize: 16, fontWeight: 800 }}>Host Space Talk</button></div>;
  const upcomingPage = <div style={{ minWidth: 0, flex: "0 0 33.333%", padding: "18px 22px 36px", boxSizing: "border-box", color: "#111418" }}><h2 style={{ margin: 0, fontSize: 24 }}>Upcoming</h2><p style={{ marginTop: 10, color: "#70757B" }}>No upcoming Space Talks yet.</p></div>;
  return <div style={{ minHeight: "100dvh", height: "100dvh", overflowY: "auto", overflowX: "hidden", WebkitOverflowScrolling: "touch", background: "#FFFFFF", color: "#111418" }}><style>{"@keyframes spaceTalkSlide{from{opacity:.3}to{opacity:1}}"}</style><header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", height: 60, padding: "18px 22px 0", boxSizing: "border-box" }}><h1 style={{ margin: 0, fontSize: 29, lineHeight: 1, letterSpacing: -1.1, fontWeight: 800 }}>Space <span style={{ color: "#D7A914" }}>Talk</span></h1><button type="button" aria-label="Space Talk notifications" style={{ border: 0, background: "transparent", padding: 6, color: "#111418" }}><Bell size={27} strokeWidth={2.1} /></button></header><div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", height: 58, alignItems: "end", borderBottom: "1px solid #EBECEE", margin: "0 22px" }}>{["Talk", "Live Video", "Upcoming"].map((label, index) => <button key={label} type="button" onClick={() => selectTab(index)} style={{ height: 42, border: 0, borderBottom: index === activeTab ? "3px solid #F4D35E" : "3px solid transparent", background: "transparent", color: index === activeTab ? "#D2A20C" : "#34383D", fontFamily: FONT, fontSize: 15, fontWeight: index === activeTab ? 750 : 500 }}>{label}</button>)}</div><div onTouchStart={onTabTouchStart} onTouchMove={onTabTouchMove} onTouchEnd={onTabTouchEnd} onTouchCancel={onTabTouchEnd} style={{ overflow: "hidden", touchAction: "pan-y" }}><div style={{ display: "flex", width: "300%", transform: "translate3d(calc(-" + (activeTab * 33.333) + "% + " + tabDragX + "px),0,0)", transition: tabDragX ? "none" : "transform 360ms cubic-bezier(.22,1,.36,1)", alignItems: "flex-start" }}>{talkPage}{activeTab === 1 ? <div style={{ minWidth: 0, flex: "0 0 33.333%" }}><LiveVideoTab account={account} /></div> : <div style={{ minWidth: 0, flex: "0 0 33.333%" }} />}{upcomingPage}</div></div></div>;
}

function talkProfileFromRow(row, fallback = {}) {
  return {
    id: row?.user_id || row?.id || fallback.id || "",
    name: row?.name || row?.display_name || row?.username || fallback.name || "Space Talk host",
    country: row?.country || row?.location || fallback.country || "Accra, Ghana",
    flag: row?.flag || row?.country_flag || fallback.flag || "🇬🇭",
    avatar_url: row?.avatar_url || row?.profile_image_url || row?.image_url || row?.avatar || fallback.avatar_url || fallback.avatar || "",
    role: row?.role || fallback.role || "listener",
    muted: row?.is_muted ?? row?.muted ?? true,
  };
}

function TalkProfileAvatar({ profile, size = 52, center = false }) {
  if (profile?.avatar_url) return <img src={profile.avatar_url} alt={profile.name || "Participant"} draggable="false" style={{ width: size, height: size, display: "block", objectFit: "cover", borderRadius: "50%", border: center ? "3px solid #F1C533" : "1px solid #D7D9DC", boxSizing: "border-box", background: "#F4F5F6" }} />;
  return <PlaceholderAvatar size={size} center={center} />;
}

function LiveRoomScreen({ onBack, account, isHost = false }) {
  const ROOM_ID = "weekly-crypto-talk";
  const localProfile = talkProfileFromRow(account || {}, { name: "Space Talk host", country: "Accra, Ghana", flag: "🇬🇭", role: isHost ? "host" : "listener" });
  const sessionIdRef = React.useRef(account?.id || "guest-" + Date.now());
  const channelRef = React.useRef(null);
  const localStreamRef = React.useRef(null);
  const peerConnectionsRef = React.useRef(new Map());
  const remoteAudioRef = React.useRef(new Map());
  const [participantId, setParticipantId] = useState(account?.id || null);
  const [participants, setParticipants] = useState([]);
  const [messages, setMessages] = useState([]);
  const [muted, setMuted] = useState(true);
  const [chatOpen, setChatOpen] = useState(false);
  const [peopleOpen, setPeopleOpen] = useState(false);
  const [requestOpen, setRequestOpen] = useState(false);
  const [requestText, setRequestText] = useState("");
  const [messageText, setMessageText] = useState("");
  const [mediaError, setMediaError] = useState("");
  const [notice, setNotice] = useState("");
  const [isEnding, setIsEnding] = useState(false);
  const [messageTick, setMessageTick] = useState(0);

  const refreshParticipants = async () => {
    const { data } = await supabase.from("space_talk_participants").select("*").eq("room_id", ROOM_ID).order("joined_at", { ascending: true });
    if (data) setParticipants(data);
  };
  const refreshMessages = async () => {
    const { data } = await supabase.from("space_talk_messages").select("*").eq("room_id", ROOM_ID).order("created_at", { ascending: true }).limit(80);
    if (data) setMessages(data);
  };
  const sendSignal = async (payload) => { if (channelRef.current) await channelRef.current.send({ type: "broadcast", event: "webrtc", payload }); };
  const createPeer = async (remoteId, initiator) => {
    if (!remoteId || remoteId === sessionIdRef.current) return null;
    if (peerConnectionsRef.current.has(remoteId)) return peerConnectionsRef.current.get(remoteId);
    const pc = new RTCPeerConnection({ iceServers: [{ urls: "stun:stun.l.google.com:19302" }] });
    peerConnectionsRef.current.set(remoteId, pc);
    if (localStreamRef.current) localStreamRef.current.getTracks().forEach((track) => pc.addTrack(track, localStreamRef.current));
    pc.onicecandidate = (event) => { if (event.candidate) sendSignal({ kind: "ice", from: sessionIdRef.current, to: remoteId, candidate: event.candidate }); };
    pc.ontrack = (event) => { const stream = event.streams?.[0]; if (!stream) return; let audio = remoteAudioRef.current.get(remoteId); if (!audio) { audio = new Audio(); audio.autoplay = true; remoteAudioRef.current.set(remoteId, audio); } audio.srcObject = stream; audio.play?.().catch(() => {}); };
    pc.onconnectionstatechange = () => { if (["failed", "closed", "disconnected"].includes(pc.connectionState)) { pc.close(); peerConnectionsRef.current.delete(remoteId); } };
    if (initiator) { const offer = await pc.createOffer(); await pc.setLocalDescription(offer); await sendSignal({ kind: "offer", from: sessionIdRef.current, to: remoteId, description: pc.localDescription }); }
    return pc;
  };
  const enableMicrophone = async () => {
    if (!navigator.mediaDevices?.getUserMedia) { setMediaError("Microphone access is not supported in this browser."); return false; }
    if (!localStreamRef.current) {
      try { localStreamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true, video: false }); } catch { setMediaError("Microphone permission is required to speak."); return false; }
      for (const [remoteId, pc] of peerConnectionsRef.current.entries()) { localStreamRef.current.getTracks().forEach((track) => pc.addTrack(track, localStreamRef.current)); const offer = await pc.createOffer(); await pc.setLocalDescription(offer); await sendSignal({ kind: "offer", from: sessionIdRef.current, to: remoteId, description: pc.localDescription }); }
    }
    localStreamRef.current.getAudioTracks().forEach((track) => { track.enabled = true; }); setMuted(false);
    if (participantId) await supabase.from("space_talk_participants").update({ is_muted: false }).eq("room_id", ROOM_ID).eq("user_id", participantId);
    return true;
  };
  const toggleMute = async () => {
    if (muted) { await enableMicrophone(); return; }
    localStreamRef.current?.getAudioTracks().forEach((track) => { track.enabled = false; }); setMuted(true);
    if (participantId) await supabase.from("space_talk_participants").update({ is_muted: true }).eq("room_id", ROOM_ID).eq("user_id", participantId);
  };
  useEffect(() => {
    let cancelled = false;
    (async () => { let id = account?.id || null; if (!id) { try { id = (await supabase.auth.getUser()).data?.user?.id || null; } catch {} } if (!cancelled && id) setParticipantId(id); })();
    return () => { cancelled = true; };
  }, [account?.id]);
  useEffect(() => {
    let cancelled = false;
    const channel = supabase.channel("space-talk-" + ROOM_ID); channelRef.current = channel;
    channel.on("broadcast", { event: "webrtc" }, async ({ payload }) => {
      if (!payload || payload.to !== sessionIdRef.current || payload.from === sessionIdRef.current) return;
      if (payload.kind === "join") { if (String(sessionIdRef.current) < String(payload.from)) await createPeer(payload.from, true); }
      else if (payload.kind === "offer") { const pc = await createPeer(payload.from, false); await pc.setRemoteDescription(payload.description); const answer = await pc.createAnswer(); await pc.setLocalDescription(answer); await sendSignal({ kind: "answer", from: sessionIdRef.current, to: payload.from, description: pc.localDescription }); }
      else if (payload.kind === "answer") { const pc = peerConnectionsRef.current.get(payload.from); if (pc) await pc.setRemoteDescription(payload.description); }
      else if (payload.kind === "ice") { const pc = peerConnectionsRef.current.get(payload.from); if (pc) await pc.addIceCandidate(payload.candidate).catch(() => {}); }
      else if (payload.kind === "end") setNotice("The host ended this Space Talk.");
    });
    channel.on("postgres_changes", { event: "*", schema: "public", table: "space_talk_participants", filter: "room_id=eq." + ROOM_ID }, refreshParticipants);
    channel.on("postgres_changes", { event: "INSERT", schema: "public", table: "space_talk_messages", filter: "room_id=eq." + ROOM_ID }, (payload) => { setMessages((current) => [...current, payload.new].slice(-80)); setMessageTick((value) => value + 1); });
    channel.subscribe(async (status) => { if (status === "SUBSCRIBED") { await sendSignal({ kind: "join", from: sessionIdRef.current }); if (!cancelled) { await refreshParticipants(); await refreshMessages(); } } });
    return () => { cancelled = true; channel.unsubscribe(); if (channelRef.current === channel) channelRef.current = null; peerConnectionsRef.current.forEach((pc) => pc.close()); peerConnectionsRef.current.clear(); remoteAudioRef.current.forEach((audio) => { audio.pause?.(); audio.srcObject = null; }); remoteAudioRef.current.clear(); localStreamRef.current?.getTracks().forEach((track) => track.stop()); localStreamRef.current = null; };
  }, [participantId]);
  useEffect(() => {
    if (!participantId) return undefined;
    let cancelled = false;
    (async () => { const row = { room_id: ROOM_ID, user_id: participantId, role: isHost ? "host" : "listener", name: localProfile.name, country: localProfile.country, flag: localProfile.flag, avatar_url: localProfile.avatar_url, is_muted: true }; const { error } = await supabase.from("space_talk_participants").upsert(row, { onConflict: "room_id,user_id" }); if (error && !cancelled) setNotice("Unable to sync your participant status."); await refreshParticipants(); })();
    return () => { cancelled = true; };
  }, [participantId, isHost]);
  const hostRow = participants.find((row) => row.role === "host" || row.is_host === true) || (isHost ? localProfile : null);
  const hostProfile = talkProfileFromRow(hostRow || {}, isHost ? localProfile : { name: "Space Talk host", country: "Accra, Ghana", flag: "🇬🇭" });
  const audience = participants.filter((row) => row.role !== "host" && row.is_host !== true).map((row) => talkProfileFromRow(row));
  const listeningCount = participants.length;
  const positions = [{ top: 112, left: 14 }, { top: 112, right: 14 }, { top: 316, left: 21 }, { top: 316, right: 21 }, { top: 462, left: "calc(50% - 31px)" }];
  const sendMessage = async (event) => { event.preventDefault(); const message = messageText.trim(); if (!message) return; const row = { room_id: ROOM_ID, user_id: participantId, message, user_name: localProfile.name, avatar_url: localProfile.avatar_url }; const { error } = await supabase.from("space_talk_messages").insert(row); if (error) setNotice("Your message could not be sent."); else setMessageText(""); };
  const submitRequest = async (event) => { event.preventDefault(); const { error } = await supabase.from("space_talk_join_requests").insert({ room_id: ROOM_ID, user_id: participantId, message: requestText.trim(), status: "pending" }); if (error) setNotice("Your request could not be sent."); else { setRequestText(""); setRequestOpen(false); setNotice("Request sent to the host."); } };
  const leaveRoom = async () => { if (isEnding) return; setIsEnding(true); if (isHost) { await supabase.from("space_talk_rooms").update({ status: "ended", is_live: false, ended_at: new Date().toISOString() }).eq("id", ROOM_ID); await sendSignal({ kind: "end", from: sessionIdRef.current }); } if (participantId) await supabase.from("space_talk_participants").delete().eq("room_id", ROOM_ID).eq("user_id", participantId); onBack(); };
  const activeMessages = messages.slice(-5);
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 30, overflow: "hidden", background: "#FFFFFF", color: "#111418", fontFamily: FONT }}>
      <style>{"@keyframes liveCommentUp{0%{opacity:0;transform:translateY(16px)}12%{opacity:1}82%{opacity:1}100%{opacity:0;transform:translateY(-18px)}}@keyframes liveMicPulse{0%,100%{box-shadow:0 0 0 0 #F4C51F33}50%{box-shadow:0 0 0 8px #F4C51F22}}"}</style>
      <header style={{ height: 90, padding: "20px 26px 0", display: "flex", alignItems: "flex-start", justifyContent: "space-between", boxSizing: "border-box" }}>
        <button type="button" onClick={leaveRoom} aria-label="Leave Space Talk" style={{ width: 42, height: 42, border: "1px solid #ECEDEF", borderRadius: "50%", background: "#FFFFFF", color: "#111418", display: "grid", placeItems: "center" }}><ChevronRight size={22} style={{ transform: "rotate(180deg)" }} /></button>
        <div style={{ textAlign: "center", paddingTop: 1 }}><div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 5, fontSize: 20, lineHeight: 1.15, fontWeight: 700 }}>Crypto Market Talk <span style={{ width: 17, height: 17, borderRadius: "50%", background: "#2C82E8", color: "#FFFFFF", fontSize: 11, display: "grid", placeItems: "center" }}>✓</span></div><div style={{ marginTop: 6, color: "#4F5358", fontSize: 15 }}>{formatCount(listeningCount)} listening</div></div>
        <button type="button" aria-label="More live room options" style={{ width: 42, height: 42, border: 0, background: "transparent", color: "#111418", display: "grid", placeItems: "center" }}><MoreHorizontal size={25} strokeWidth={2.5} /></button>
      </header>
      <main style={{ position: "relative", height: "calc(100% - 178px)", minHeight: 0, overflow: "hidden" }}>
        <div style={{ position: "absolute", inset: "0 22px 0", pointerEvents: "none" }}>
          <span style={{ position: "absolute", top: 33, left: "calc(50% - 28px)", padding: "7px 15px", border: "1px solid #E5E6E8", borderRadius: 13, background: "#FFFFFF", color: "#D4A914", fontSize: 14, fontWeight: 650 }}>Host</span>
          <span style={{ position: "absolute", top: 95, left: "calc(50% - 94px)", width: 188, height: 188, border: "1px solid #E8EAEC", borderRadius: "50%", boxSizing: "border-box" }} /><span style={{ position: "absolute", top: 128, left: "calc(50% - 145px)", width: 290, height: 290, border: "1px solid #EEF0F1", borderRadius: "50%", boxSizing: "border-box" }} /><span style={{ position: "absolute", top: 190, left: "calc(50% - 185px)", width: 370, height: 370, border: "1px solid #F1F2F3", borderRadius: "50%", boxSizing: "border-box" }} />
          <div style={{ position: "absolute", top: 150, left: "calc(50% - 67px)", width: 134, height: 134, display: "grid", placeItems: "center", border: "3px solid #F1C533", borderRadius: "50%", background: "#FFFFFF", boxSizing: "border-box", animation: muted ? "none" : "liveMicPulse 1.5s ease-in-out infinite" }}><TalkProfileAvatar profile={hostProfile} size={126} center /></div>
          <div style={{ position: "absolute", top: 276, left: "calc(50% - 19px)", width: 38, height: 38, borderRadius: "50%", background: "#F5BC05", color: "#111418", display: "grid", placeItems: "center", boxShadow: "0 2px 5px #D8A90055" }}><Mic size={19} strokeWidth={2.2} /></div>
          <div style={{ position: "absolute", top: 290, left: 0, right: 0, textAlign: "center" }}><strong style={{ display: "block", fontSize: 19, fontWeight: 700 }}>{hostProfile.name}</strong><span style={{ display: "block", marginTop: 7, fontSize: 15 }}>{hostProfile.flag} {hostProfile.country}</span></div>
          {audience.slice(0, 5).map((profile, index) => <div key={profile.id || profile.name + "-" + index} style={{ position: "absolute", ...positions[index], width: 100, textAlign: "center" }}><span style={{ display: "inline-grid", position: "relative", placeItems: "center", width: 72, height: 72, border: "1px solid #D8DADD", borderRadius: "50%", background: "#FFFFFF", boxSizing: "border-box" }}><TalkProfileAvatar profile={profile} size={66} /><span style={{ position: "absolute", right: -1, bottom: 0, width: 20, height: 20, borderRadius: "50%", background: "#2D82E9", border: "2px solid #FFFFFF", color: "#FFFFFF", display: "grid", placeItems: "center" }}><Mic size={10} strokeWidth={2.4} /></span></span><strong style={{ display: "block", marginTop: 7, fontSize: 15, lineHeight: 1.1 }}>{profile.name}</strong><span style={{ display: "block", marginTop: 7, fontSize: 13, whiteSpace: "nowrap" }}>{profile.flag} {profile.country}</span></div>)}
        </div>
        {messages.length > 0 && <div aria-live="polite" style={{ position: "absolute", right: 12, bottom: 24, width: 190, display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 5, pointerEvents: "none" }}>{activeMessages.map((item, index) => <span key={item.id || item.created_at + "-" + index + "-" + messageTick} style={{ maxWidth: "100%", padding: "7px 10px", borderRadius: 15, background: "#111418D9", color: "#FFFFFF", fontSize: 12, lineHeight: 1.25, animation: "liveCommentUp 4.6s ease-out both" }}><b style={{ color: "#F4D35E" }}>{item.user_name || "Trader"}</b> {item.message || item.content}</span>)}</div>}
      </main>
      <footer style={{ height: 88, padding: "0 21px 13px", display: "flex", alignItems: "flex-end", justifyContent: "space-between", boxSizing: "border-box" }}>
        <button type="button" onClick={() => setRequestOpen(true)} aria-label="Request to join" style={{ border: 0, background: "transparent", color: "#111418", display: "flex", flexDirection: "column", alignItems: "center", gap: 7, fontFamily: FONT, fontSize: 12 }}><span style={{ width: 47, height: 47, border: "1px solid #ECEDEF", borderRadius: "50%", display: "grid", placeItems: "center" }}><Hand size={22} /></span>Request</button>
        <button type="button" onClick={() => setChatOpen(true)} aria-label="Open chat" style={{ border: 0, background: "transparent", color: "#111418", display: "flex", flexDirection: "column", alignItems: "center", gap: 7, fontFamily: FONT, fontSize: 12 }}><span style={{ width: 47, height: 47, border: "1px solid #ECEDEF", borderRadius: "50%", display: "grid", placeItems: "center" }}><MessageCircle size={21} /></span>Chat</button>
        <button type="button" onClick={toggleMute} aria-label={muted ? "Speak" : "Mute microphone"} style={{ border: 0, background: "transparent", color: "#111418", display: "flex", flexDirection: "column", alignItems: "center", gap: 7, fontFamily: FONT, fontSize: 12 }}><span style={{ width: 66, height: 66, marginTop: -19, border: "3px solid #F4D35E", borderRadius: "50%", background: muted ? "#F8C300" : "#F4D35E", display: "grid", placeItems: "center", boxShadow: muted ? "0 2px 4px #D8A90055" : "0 0 0 7px #F4D35E33" }}>{muted ? <Mic size={28} /> : <MicOff size={28} />}</span>Speak</button>
        <button type="button" onClick={() => setPeopleOpen(true)} aria-label="Show people" style={{ border: 0, background: "transparent", color: "#111418", display: "flex", flexDirection: "column", alignItems: "center", gap: 7, fontFamily: FONT, fontSize: 12 }}><span style={{ width: 47, height: 47, border: "1px solid #ECEDEF", borderRadius: "50%", display: "grid", placeItems: "center" }}><UsersRound size={22} /></span>People</button>
        <button type="button" onClick={leaveRoom} aria-label="Leave room" style={{ border: 0, background: "transparent", color: "#C72929", display: "flex", flexDirection: "column", alignItems: "center", gap: 7, fontFamily: FONT, fontSize: 12 }}><span style={{ width: 47, height: 47, border: "1px solid #ECEDEF", borderRadius: "50%", display: "grid", placeItems: "center" }}><PhoneOff size={21} /></span>Leave</button>
      </footer>
      {notice && <button type="button" onClick={() => setNotice("")} style={{ position: "absolute", left: 18, right: 18, bottom: 94, border: 0, borderRadius: 12, padding: "10px 14px", background: "#111418", color: "#FFFFFF", fontFamily: FONT, fontSize: 13 }}>{notice}</button>}
      {mediaError && <button type="button" onClick={() => setMediaError("")} style={{ position: "absolute", left: 18, right: 18, bottom: 94, border: 0, borderRadius: 12, padding: "10px 14px", background: "#FFF2F2", color: "#A52222", fontFamily: FONT, fontSize: 13 }}>{mediaError}</button>}
      {(chatOpen || peopleOpen || requestOpen) && <div style={{ position: "absolute", inset: 0, zIndex: 5, background: "#11141822" }} onClick={() => { setChatOpen(false); setPeopleOpen(false); setRequestOpen(false); }} />}
      {chatOpen && <section style={{ position: "absolute", zIndex: 6, left: 0, right: 0, bottom: 0, maxHeight: "68%", padding: "18px 18px 22px", borderRadius: "24px 24px 0 0", background: "#FFFFFF", boxShadow: "0 -8px 24px #1114181A" }} onClick={(event) => event.stopPropagation()}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><strong style={{ fontSize: 18 }}>Live chat</strong><button type="button" onClick={() => setChatOpen(false)} style={{ border: 0, background: "transparent", fontSize: 22 }}>×</button></div><div style={{ maxHeight: 230, overflowY: "auto", padding: "12px 0" }}>{messages.map((item, index) => <p key={item.id || index} style={{ margin: "8px 0", fontSize: 13 }}><b>{item.user_name || "Trader"}</b> {item.message || item.content}</p>)}</div><form onSubmit={sendMessage} style={{ display: "flex", gap: 8 }}><input value={messageText} onChange={(event) => setMessageText(event.target.value)} placeholder="Say something..." style={{ flex: 1, minWidth: 0, border: "1px solid #E1E3E5", borderRadius: 18, padding: "11px 13px", fontFamily: FONT, outline: "none" }} /><button type="submit" style={{ border: 0, borderRadius: 18, padding: "0 16px", background: "#F4C51F", fontFamily: FONT, fontWeight: 700 }}>Send</button></form></section>}
      {peopleOpen && <section style={{ position: "absolute", zIndex: 6, left: 0, right: 0, bottom: 0, maxHeight: "72%", overflowY: "auto", padding: "18px 20px 24px", borderRadius: "24px 24px 0 0", background: "#FFFFFF", boxShadow: "0 -8px 24px #1114181A" }} onClick={(event) => event.stopPropagation()}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><strong style={{ fontSize: 18 }}>People ({participants.length})</strong><button type="button" onClick={() => setPeopleOpen(false)} style={{ border: 0, background: "transparent", fontSize: 22 }}>×</button></div>{participants.map((row, index) => { const profile = talkProfileFromRow(row); return <div key={row.id || row.user_id || index} style={{ display: "flex", alignItems: "center", gap: 12, padding: "13px 0", borderBottom: "1px solid #F0F1F2" }}><TalkProfileAvatar profile={profile} size={42} /><span style={{ flex: 1 }}><b style={{ display: "block" }}>{profile.name}</b><small>{profile.flag} {profile.country}</small></span><small>{profile.role === "host" ? "Host" : profile.muted ? "Muted" : "Speaking"}</small></div>; })}</section>}
      {requestOpen && <section style={{ position: "absolute", zIndex: 6, left: 0, right: 0, bottom: 0, padding: "20px 20px 26px", borderRadius: "24px 24px 0 0", background: "#FFFFFF", boxShadow: "0 -8px 24px #1114181A" }} onClick={(event) => event.stopPropagation()}><strong style={{ display: "block", fontSize: 19 }}>Request to join</strong><p style={{ margin: "7px 0 14px", color: "#646970", fontSize: 13 }}>Ask the host to bring you on stage.</p><form onSubmit={submitRequest}><textarea value={requestText} onChange={(event) => setRequestText(event.target.value)} placeholder="Add a note (optional)" rows={3} style={{ width: "100%", resize: "none", border: "1px solid #E1E3E5", borderRadius: 14, padding: 12, boxSizing: "border-box", fontFamily: FONT, outline: "none" }} /><div style={{ display: "flex", justifyContent: "flex-end", gap: 10, marginTop: 12 }}><button type="button" onClick={() => setRequestOpen(false)} style={{ border: 0, background: "#F2F3F4", borderRadius: 14, padding: "11px 16px", fontFamily: FONT }}>Cancel</button><button type="submit" style={{ border: 0, background: "#F4C51F", borderRadius: 14, padding: "11px 16px", fontFamily: FONT, fontWeight: 700 }}>Send request</button></div></form></section>}
    </div>
  );
}

export default function MoreLandingOverride({ account }) {
  const [analytics, setAnalytics] = useState({ views: 0, followers: 0, likes: 0 });
  const [spaceTalkDiscovery, setSpaceTalkDiscovery] = useState(false);
  const [spaceTalkRoom, setSpaceTalkRoom] = useState(false);
  const [spaceTalkHost, setSpaceTalkHost] = useState(false);
  const [pagerPosition, setPagerPosition] = useState(0);
  const [pagerDragging, setPagerDragging] = useState(false);
  const pagerViewportRef = React.useRef(null);
  const pagerGesture = React.useRef(null);
  const suppressPagerClick = React.useRef(false);
  const [moreOverlay, setMoreOverlay] = useState(() => {
    try { return window.history.state?.rainxMoreOverlay || null; } catch { return null; }
  });

  useEffect(() => {
    const onPop = (event) => setMoreOverlay(event.state?.rainxMoreOverlay || null);
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const openOverlay = (screen) => {
    const state = { ...(window.history.state || {}), rainxMoreOverlay: screen };
    window.history.pushState(state, "", window.location.href);
    setMoreOverlay(screen);
  };
  const backOverlay = () => {
    if (window.history.state?.rainxMoreOverlay) { window.history.back(); return; }
    setMoreOverlay(null);
  };

  const overlayDepth = (overlay) => ({ gifts: 1, "gifts-settings": 2, referrals: 1, "referral-activity": 2, "referral-performance": 3 }[overlay] || 0);
  const [renderedOverlay, setRenderedOverlay] = useState(moreOverlay);
  const [overlayTransition, setOverlayTransition] = useState(null);

  useEffect(() => {
    if (moreOverlay === renderedOverlay) return undefined;
    const from = renderedOverlay;
    const to = moreOverlay;
    const direction = !to || overlayDepth(to) < overlayDepth(from) ? "back" : "forward";
    setOverlayTransition({ from, to, direction });
    const timer = window.setTimeout(() => {
      setRenderedOverlay(to);
      setOverlayTransition(null);
    }, 360);
    return () => window.clearTimeout(timer);
  }, [moreOverlay, renderedOverlay]);

  const renderOverlay = (overlay, style) => {
    if (!overlay) return null;
    if (overlay === "gifts" || overlay === "gifts-settings") return <GiftsRewardsScreen key={overlay} settingsOpen={overlay === "gifts-settings"} transitionStyle={style} onOpenSettings={() => openOverlay("gifts-settings")} onBackFromSettings={backOverlay} onBack={backOverlay} account={account} />;
    if (overlay === "referrals") return <ReferralRewardsScreen key={overlay} count={0} earnings={0} referralCode={null} transitionStyle={style} onBack={backOverlay} onActivity={() => openOverlay("referral-activity")} />;
    if (overlay === "referral-activity") return <MyReferralsScreen key={overlay} count={0} earnings={0} referralCode={null} account={account} transitionStyle={style} onBack={backOverlay} onActivity={() => openOverlay("referral-performance")} />;
    if (overlay === "referral-performance") return <ReferralPerformanceScreen key={overlay} transitionStyle={style} onBack={backOverlay} />;
    return null;
  };

  useEffect(() => {
    let cancelled = false;
    if (account?.id) {
      loadCreatorAnalytics(account.id).then((data) => {
        if (!cancelled) setAnalytics(data);
      }).catch(() => {});
    }
    return () => { cancelled = true; };
  }, [account?.id]);


  const settlePager = (position) => {
    setPagerDragging(false);
    setPagerPosition(position);
  };
  const onPagerPointerDown = (event) => {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    pagerGesture.current = { startX: event.clientX, startY: event.clientY, startPosition: pagerPosition, lastX: event.clientX, lastTime: Date.now(), dragging: false };
  };
  const onPagerPointerMove = (event) => {
    const active = pagerGesture.current;
    if (!active) return;
    const dx = event.clientX - active.startX;
    const dy = event.clientY - active.startY;
    if (!active.dragging) {
      if (Math.abs(dx) < 6 || Math.abs(dx) <= Math.abs(dy)) return;
      active.dragging = true;
      suppressPagerClick.current = false;
      event.currentTarget.setPointerCapture?.(event.pointerId);
      setPagerDragging(true);
    }
    event.preventDefault();
    const width = pagerViewportRef.current?.clientWidth || 1;
    setPagerPosition(Math.max(0, Math.min(1, active.startPosition - dx / width)));
    active.lastX = event.clientX;
    active.lastTime = Date.now();
  };
  const onPagerPointerUp = (event) => {
    const active = pagerGesture.current;
    if (!active) return;
    if (active.dragging) {
      const elapsed = Math.max(1, Date.now() - active.lastTime);
      const velocity = (event.clientX - active.lastX) / elapsed;
      const target = Math.abs(velocity) > 0.7 ? (velocity < 0 ? 1 : 0) : (pagerPosition >= 0.5 ? 1 : 0);
      suppressPagerClick.current = true;
      setPagerPosition(target);
      setPagerDragging(false);
      event.currentTarget.releasePointerCapture?.(event.pointerId);
    }
    pagerGesture.current = null;
  };
  const onPagerClickCapture = (event) => {
    if (suppressPagerClick.current) {
      event.preventDefault();
      event.stopPropagation();
      suppressPagerClick.current = false;
    }
  };

  if (spaceTalkRoom) {
    return <LiveRoomScreen account={account} isHost={spaceTalkHost} onBack={() => setSpaceTalkRoom(false)} />;
  }

  if (spaceTalkDiscovery) {
    return <SpaceTalkDiscoveryScreen account={account} onOpenLiveRoom={(host) => { setSpaceTalkHost(Boolean(host)); setSpaceTalkRoom(true); }} />;
  }

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "#FFFFFF",
        color: "#111418",
        fontFamily: FONT,
        overflow: "hidden",
        width: "100%",
        height: "100%",
        contain: "layout paint size",
        overscrollBehavior: "none",
      }}
    >
      <div
        style={{
          height: "100%",
          minHeight: 0,
          width: "100%",
          boxSizing: "border-box",
          overflowY: "auto",
          overflowX: "hidden",
          overscrollBehaviorY: "none",
          overscrollBehaviorX: "none",
          WebkitOverflowScrolling: "touch",
          touchAction: "pan-y",
          scrollbarWidth: "none",
          padding: "0 14px 18px",
        }}
      >
        <header
          style={{
            height: 72,
            position: "relative",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <button
            type="button"
            aria-label="Back"
            onClick={() => go("#home")}
            style={{
              position: "absolute",
              left: -3,
              top: 16,
              width: 40,
              height: 40,
              border: 0,
              background: "transparent",
              display: "grid",
              placeItems: "center",
              color: "#111418",
              padding: 0,
            }}
          >
            <ArrowLeft size={28} strokeWidth={2.15} />
          </button>
          <div
            style={{
              fontSize: 21,
              lineHeight: 1,
              fontWeight: 800,
              letterSpacing: -0.7,
            }}
          >
            Trader’s Space
          </div>
        </header>

        <div style={{ height: 52, position: "relative", display: "grid", gridTemplateColumns: "1fr 1fr", borderBottom: "1px solid #E7E8EA", marginBottom: 16 }}>
          <button type="button" onClick={() => settlePager(0)} style={{ border: 0, background: "transparent", color: pagerPosition < 0.5 ? "#111418" : "#858A91", fontFamily: FONT, fontSize: 16, fontWeight: pagerPosition < 0.5 ? 800 : 700 }}>Posts</button>
          <button type="button" onClick={() => settlePager(1)} style={{ border: 0, background: "transparent", color: pagerPosition >= 0.5 ? "#111418" : "#858A91", fontFamily: FONT, fontSize: 16, fontWeight: pagerPosition >= 0.5 ? 800 : 700 }}>Space Talk</button>
          <div aria-hidden="true" style={{ position: "absolute", left: 0, bottom: -1, width: "50%", height: 3, background: "#111418", transform: `translateX(${pagerPosition * 100}%)`, transition: pagerDragging ? "none" : "transform 360ms cubic-bezier(.22,1,.36,1)" }} />
        </div>

        <div ref={pagerViewportRef} onPointerDown={onPagerPointerDown} onPointerMove={onPagerPointerMove} onPointerUp={onPagerPointerUp} onPointerCancel={onPagerPointerUp} onClickCapture={onPagerClickCapture} style={{ width: "100%", overflow: "hidden", touchAction: "pan-y" }}>
          <div style={{ display: "flex", alignItems: "flex-start", width: "200%", transform: `translate3d(${-(pagerPosition * 50)}%, 0, 0)`, transition: pagerDragging ? "none" : "transform 360ms cubic-bezier(.22,1,.36,1)", willChange: "transform" }}>
            <div style={{ flex: "0 0 50%", width: "50%", minWidth: 0 }}>

        <section
          style={{
            ...cardStyle,
            padding: "20px 20px 18px",
            marginBottom: 16,
          }}
        >
          <button
            type="button"
            onClick={() => go("#more")}
            style={{
              width: "100%",
              padding: 0,
              border: 0,
              background: "transparent",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              color: "#111418",
              textAlign: "left",
            }}
          >
            <span
              style={{
                fontSize: 20,
                fontWeight: 800,
                letterSpacing: -0.45,
              }}
            >
              Analytics
            </span>
            <ChevronRight size={25} strokeWidth={2.15} />
          </button>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
              columnGap: 10,
              marginTop: 22,
            }}
          >
            {[
              ["Post views", formatCount(analytics.views)],
              ["Net followers", formatCount(analytics.followers)],
              ["Likes", formatCount(analytics.likes)],
            ].map(([label, value]) => (
              <div key={label} style={{ minWidth: 0 }}>
                <div
                  style={{
                    fontSize: 13,
                    lineHeight: 1.25,
                    fontWeight: 700,
                    marginBottom: 7,
                    whiteSpace: "nowrap",
                    letterSpacing: -0.15,
                  }}
                >
                  {label}
                </div>
                <div
                  style={{
                    fontSize: 29,
                    lineHeight: 1,
                    fontWeight: 800,
                    letterSpacing: -1,
                  }}
                >
                  {value}
                </div>
                <div
                  style={{
                    marginTop: 11,
                    fontSize: 13,
                    lineHeight: 1,
                    color: "#329CE6",
                    fontWeight: 700,
                  }}
                >
                  ▲ 7d
                </div>
              </div>
            ))}
          </div>
        </section>

        <button
          type="button"
          onClick={() => go("#more/verification")}
          aria-label="Get Verified"
          style={{
            display: "block",
            width: "100%",
            padding: 0,
            margin: "0 0 16px",
            border: 0,
            outline: "none",
            background: "transparent",
            overflow: "visible",
          }}
        >
          <img
            src={ASSET.verified}
            alt="Get Verified — Earn your badge & unlock exclusive rewards"
            draggable="false"
            style={{
              display: "block",
              width: "100%",
              height: "auto",
              border: 0,
              outline: "none",
            }}
          />
        </button>

        <section
          style={{
            ...cardStyle,
            padding: "20px 20px 18px",
            marginBottom: 12,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              marginBottom: 16,
            }}
          >
            <div
              style={{
                fontSize: 20,
                fontWeight: 800,
                letterSpacing: -0.45,
              }}
            >
              Monetisation
            </div>
            <ChevronRight size={25} strokeWidth={2.15} />
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: 12,
            }}
          >
            <button
              type="button"
              onClick={() => go("#more/rewards")}
              style={imageButtonStyle}
            >
              <img
                src={ASSET.gold}
                alt="Grab Rewards for your 10K+ posts views"
                draggable="false"
                style={imageStyle}
              />
            </button>

            <button
              type="button"
              onClick={() => go("#more/rewards")}
              style={imageButtonStyle}
            >
              <img
                src={ASSET.black}
                alt="monetize in the same orbit"
                draggable="false"
                style={imageStyle}
              />
            </button>
          </div>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
              gap: 10,
              marginTop: 13,
            }}
          >
            {[
              ["Gifts", Gift, "#more/rewards", true],
              ["Referrals", UsersRound, "#more/referrals", false, "referrals"],
              ["Space Talk\nEarnings", CircleDollarSign, "#more/rewards"],
            ].map(([label, Icon, route, gift, referral]) => (
              <button
                key={label}
                type="button"
                onClick={() => gift ? openOverlay("gifts") : referral ? openOverlay("referrals") : go(route)}
                style={{
                  minWidth: 0,
                  border: 0,
                  background: "transparent",
                  color: "#111418",
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  padding: 0,
                  fontFamily: FONT,
                }}
              >
                <span
                  style={{
                    width: "100%",
                    height: 54,
                    border: "1px solid #E4E6E8",
                    borderRadius: 13,
                    background: "#F5F6F7",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxSizing: "border-box",
                  }}
                >
                  <Icon size={20} strokeWidth={2.05} />
                </span>
                <span
                  style={{
                    marginTop: 6,
                    fontSize: 11,
                    lineHeight: 1.18,
                    fontWeight: 600,
                    whiteSpace: "pre-line",
                    textAlign: "center",
                  }}
                >
                  {label}
                </span>
              </button>
            ))}
          </div>

          <button
            type="button"
            onClick={() => go("#more/rewards")}
            style={{
              width: "100%",
              height: 40,
              marginTop: 16,
              border: 0,
              borderRadius: 12,
              background: "#F1F2F3",
              color: "#111418",
              fontFamily: FONT,
              fontSize: 14,
              fontWeight: 800,
            }}
          >
            More ways to get paid
          </button>
        </section>
            </div>
            <div style={{ flex: "0 0 50%", width: "50%", minWidth: 0 }}>
              <SpaceTalkScreen onOpenDiscovery={() => setSpaceTalkDiscovery(true)} />
            </div>
          </div>
        </div>
      </div>
      <style>{"@keyframes rainxMorePushIn{from{transform:translateX(100%)}to{transform:translateX(0)}}@keyframes rainxMorePushOut{from{transform:translateX(0)}to{transform:translateX(-100%)}}@keyframes rainxMorePopIn{from{transform:translateX(-100%)}to{transform:translateX(0)}}@keyframes rainxMorePopOut{from{transform:translateX(0)}to{transform:translateX(100%)}}"}</style>
      {overlayTransition ? <>
        {renderOverlay(overlayTransition.from, { zIndex: 1099, pointerEvents: "none", animation: overlayTransition.direction === "forward" ? "rainxMorePushOut .36s cubic-bezier(.22,1,.36,1) both" : "rainxMorePopOut .36s cubic-bezier(.22,1,.36,1) both" })}
        {renderOverlay(overlayTransition.to, { zIndex: 1100, animation: overlayTransition.direction === "forward" ? "rainxMorePushIn .36s cubic-bezier(.22,1,.36,1) both" : "rainxMorePopIn .36s cubic-bezier(.22,1,.36,1) both" })}
      </> : renderOverlay(renderedOverlay, {})}
    </div>
  );
}

const imageButtonStyle = {
  display: "block",
  width: "100%",
  padding: 0,
  border: 0,
  outline: "none",
  borderRadius: 0,
  overflow: "visible",
  background: "transparent",
};

const imageStyle = {
  display: "block",
  width: "100%",
  height: "auto",
  aspectRatio: "292 / 331",
  objectFit: "cover",
  objectPosition: "center",
  border: 0,
  outline: "none",
};
